class IncorrectStatus(Exception):
    """
    Raised when status is different than expected.
    """
    pass


class HwNotReachable(Exception):
    """
    Raised when hw not found.
    """


class RmodIdForCellIdNotFound(Exception):
    """
    Raised when RMOD index for cell ID could not be found.
    """
    pass


class InvalidCellVariant(Exception):
    """
    Raised when provided cell variant does not exist:.
    """
    pass


class MissingExpectedStatuses(Exception):
    """
    Raised when expected statuses are missing.
    """
    pass


class InvalidBBMODvariant(Exception):
    """
    Raised when provided Bbmod variant does not exist.
    """
    pass


class InvalidRATvariant(Exception):
    """
    Raised when provided Rat variant does not exist.
    """
    pass


class InvalidSmodVariant(Exception):
    """
    Raised when provided SMOD variant does not exist.
    """
    pass


class InvalidRmodVariant(Exception):
    """
    Raised when provided status variant does not exist.
    """
    pass
